package com.foodordering.payment; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@Entity public class Payment {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long paymentId; @Column(unique=true) Long orderId; BigDecimal amount; @Enumerated(EnumType.STRING) PaymentStatus paymentStatus; LocalDateTime paymentDate; String paymentMethod; static Payment of(Long o,BigDecimal a,String method,PaymentStatus s){Payment p=new Payment();p.orderId=o;p.amount=a;p.paymentMethod=method;p.paymentStatus=s;p.paymentDate=LocalDateTime.now();return p;}} enum PaymentStatus{SUCCESS,FAILED}
